// BAD: 512-bit pragma + 4-wide walk
#pragma HLS INTERFACE m_axi port=A max_widen_bitwidth=512
#pragma HLS ARRAY_PARTITION variable=A_loc cyclic factor=4 dim=2
for (int k = 0; k < K; k += 4) { PIPELINE II=1; UNROLL l<4; A_loc[i][k+l]=A[i][k+l]; }
// GOOD: LANES=16 walk + factor=16 on the consecutive dim.

// BAD (asks HLS to move whole row per cycle):
for (int i = 0; i < TILE_SIZE; i++) {
#pragma HLS PIPELINE II=1
    for (int j = 0; j < N; j++) A[i][j] = local_A[i][j];
    y[i] = local_y[i];
}
// GOOD:
for (int i = 0; i < TILE_SIZE; i++) {
    for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
        A[i][j] = local_A[i][j];
    }
    y[i] = local_y[i];
}

// BAD: stacked outer-pipelined row loops in one task
void load_all(...) {
    for (int i = 0; i < TILE_SIZE; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) local_A[i][j] = A[...][j];
    }
    for (int i = 0; i < TILE_SIZE; i++) {
#pragma HLS PIPELINE II=1
        for (int j = 0; j < N; j++) local_B[i][j] = B[...][j];
    }
}
// GOOD: innermost pipeline per matrix or flat fused index
for (int i = 0; i < TILE_SIZE; i++) {
    for (int j = 0; j < N; j++) {
#pragma HLS PIPELINE II=1
        local_A[i][j] = A[tile_i + i][j];
    }
}

